const $=id=>document.getElementById(id),cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let selected='alex',filter='all',result=null,detailView='current';
function inputs(){return {weeks:+$('weeks').value,budget:+$('budget').value,department:$('department').value,closing:$('closing').checked,competition:$('competition').checked};}function assumptions(){return Object.fromEntries(['hire','severance','onboard','admin'].map(id=>{const el=$(id),value=Math.max(0,Math.min(+el.max,Number(el.value)||0));el.value=value;return [id,value];}));}
function scope(){return scenarioScope(inputs());}
function moveFor(id){return result?.moves.find(m=>m.person.id===id);}
function reason(person){const options=scope().vacancies.map(j=>candidate(person,j)),eligible=options.filter(c=>c.eligible),v=inputs();if(!eligible.length){const nearest=options.sort((a,b)=>b.shared.length-a.shared.length)[0];return {heading:'No suitable opening in this demo',text:nearest.shared.length?`Closest role: ${nearest.job.title}. ${nearest.shared.length} of ${nearest.job.skills.length} required skills are listed. Missing: ${nearest.missing.join(', ')}. This goes beyond the short training scope.`:'None of the available openings overlaps with the currently listed skills. A short AI course alone would not establish the skills these roles require.',next:'Next step: validate the skill inventory and search other departments. No employment decision is implied.'};}if(result){const feasible=eligible.filter(c=>c.weeks<=v.weeks&&c.training<=v.budget);const filled=feasible.filter(c=>result.moves.some(m=>m.job.id===c.job.id));if(feasible.length&&filled.length===feasible.length){const winners=filled.map(c=>result.moves.find(m=>m.job.id===c.job.id).person.name);return {heading:'Skills fit, but the vacancy is allocated',text:`${person.name.split(' ')[0]} meets the skill rule, but the available places are proposed for ${[...new Set(winners)].join(', ')} under the overall allocation. See the candidate comparison for skills and training differences.`,next:'Explore broader roles while the hiring manager reviews this proposal. Being unplaced is not a judgment of performance.'};}}if(eligible.every(c=>c.weeks>v.weeks))return {heading:'More training time needed',text:`The closest eligible role needs ${Math.min(...eligible.map(c=>c.weeks))} weeks of training. Your current limit is ${v.weeks} weeks.`,next:'Try a longer training window, then review the learning plan with the employee.'};return {heading:'No place within the current plan',text:'A suitable role exists, but the available training budget or vacancy allocation does not support this move in the current scenario.',next:'Try increasing the training budget or reviewing additional vacancies.'};}
function renderPeople(){const cohort=scope().people;const visible=cohort.filter(p=>filter==='all'||(filter==='match'?!!moveFor(p.id):result&&!moveFor(p.id)));if(visible.length&&!visible.some(p=>p.id===selected))selected=visible[0].id;else if(!visible.length)selected=null;$('teamCount').textContent=String(cohort.length).padStart(2,'0');$('teamScope').textContent=$('department').value==='all'?'Your team':$('department').value;$('people').innerHTML=visible.length?visible.map(p=>`<button class="person ${selected===p.id?'selected':''}" data-person="${p.id}" aria-pressed="${selected===p.id}"><span class="avatar">${p.initials}</span><span class="personinfo"><b>${p.name}</b><small>${p.role}</small><small class="sourceDepartment">${p.department}${result&&!moveFor(p.id)?' · broader options: '+careerPossibilities(p,inputs()).length:''}</small></span><span class="mini ${result?moveFor(p.id)?'match':'none':''}">${result?moveFor(p.id)?'Possible move':'No match':'View skills'}</span><span class="chev">›</span></button>`).join(''):'<div class="emptylist">No people in this view. Try “All”.</div>';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.disabled=!result&&b.dataset.filter!=='all';});renderDetail();}
function renderDetail(){if(!selected){$('detail').innerHTML='<div class="placeholder"><h4>No people in this view</h4><p>Choose another status filter or department.</p></div>';return;}const p=scope().people.find(p=>p.id===selected),m=moveFor(p.id),a=assumptions();let html=`<div class="detailhead"><span class="avatar">${p.initials}</span><div><h3>${p.name}</h3><p>${p.role} · ${cash(p.salary)}/year</p><p style="margin-top:5px">${p.department}</p></div></div><div class="sublabel">CURRENT SKILLS</div><div class="skills">${p.skills.map(s=>`<span class="skill ${m?.shared.includes(s)?'yes':''}">${s}</span>`).join('')}</div>`;
html+=`<div class="roleviewtabs" role="tablist" aria-label="Role possibilities"><button role="tab" aria-selected="${detailView==='current'}" data-detail-view="current" class="${detailView==='current'?'active':''}">Current openings</button><button role="tab" aria-selected="${detailView==='broader'}" data-detail-view="broader" class="${detailView==='broader'?'active':''}">Broader possibilities <span>${careerPossibilities(p,inputs()).length}</span></button></div><div class="${detailView==='current'?'':'hidden'}">`;if(!result){html+=`<div class="placeholder"><span class="largeicon">↗</span><h4>Could ${p.name.split(' ')[0]} fill an open role?</h4><p>${p.note}<br>Run matching to see role options, skill gaps and costs.</p><button class="primary" id="detailAnalyze">Find internal matches ↗</button></div>`;}else if(m){const personalSaving=p.salary/52*a.severance+a.hire+a.onboard-m.training-a.admin;html+=`<div class="targetrole"><div class="topline"><span>PROPOSED INTERNAL MOVE</span><span>${m.shared.length} / ${m.job.skills.length} skills present</span></div><h4>${m.job.title}</h4><p>${m.job.department} · Vacancy ${m.job.id.toUpperCase()}</p></div><p class="explain">${m.shared.join(', ')} transfer to this role. ${m.missing.length?'Build the missing skill before moving.':'All listed required skills are present.'}</p><div class="skills">${m.missing.map(s=>`<span class="skill gap">+ Learn ${s}</span>`).join('')}</div><div class="trainrow"><span>Training time</span><b>${m.weeks} weeks</b></div><div class="trainrow"><span>Training cost · demo quote</span><b>${cash(m.training)}</b></div><div class="trainrow"><span>Destination salary · both hiring paths</span><b>${cash(m.job.salary)}/year</b></div><p class="footnote">${m.job.salaryNote}. Salary changes are excluded from the transition cost comparison.</p><div class="individualsaving"><span>${personalSaving>=0?'Estimated transition cost avoided':'Additional transition cost'}</span><b>${cash(Math.abs(personalSaving))}</b></div><details class="costdetail"><summary>See this person's cost comparison</summary><div class="costrow"><span>Severance if exited (${a.severance} weeks)</span><b>${cash(p.salary/52*a.severance)}</b></div><div class="costrow"><span>External recruiting + onboarding</span><b>${cash(a.hire+a.onboard)}</b></div><div class="costrow"><span>Instead: training + transfer admin</span><b>${cash(m.training+a.admin)}</b></div></details><details class="costdetail"><summary>View the learning plan</summary>${m.missing.map(s=>`<h4>${m.job.trainable[s].course}</h4><ol>${m.job.trainable[s].lessons.map(l=>`<li style="margin:10px 0;line-height:1.7">${l}</li>`).join('')}</ol>`).join('')}<p>Proposed curriculum. Confirm proficiency through supervised work before transfer.</p></details>`;}else{const r=reason(p);html+=`<div class="unmatched"><h4>${r.heading}</h4><p>${r.text}</p><small>${r.next}</small></div><p class="explain">This employee has useful skills. The current vacancy list and training scope do not provide a validated move.</p><button class="outline futurelink" data-detail-view="broader">Explore broader role possibilities ↗</button>`;}html+='</div>'+futureMarkup(p);$('detail').innerHTML=html;const b=$('detailAnalyze');if(b)b.onclick=()=>run();}
function renderEconomics(){if(!result)return;const c=costComparison(result,assumptions()),count=result.moves.length,total=result.people.length,openings=result.vacancies.length,rows=(arr)=>arr.map(([k,v])=>`<div class="costrow"><span>${k}</span><b>${cash(v)}</b></div>`).join('');$('economicsContent').className='';$('economicsContent').innerHTML=`<div class="costgrid"><div class="costcard"><h3>Lay off ${total} + hire externally</h3><strong>${cash(c.baseline)}</strong><div class="costbar"><i style="width:100%"></i></div>${rows([[`Severance for ${total} ${total===1?'person':'people'}`,c.allSeverance],[`Recruiting + onboarding for ${openings}`,c.baselineHiring]])}<p>${openings} available ${openings===1?'vacancy still needs':'vacancies still need'} to be filled.</p></div><div class="costcard alt"><h3>Move ${count} internally + fill the rest</h3><strong>${cash(c.alternative)}</strong><div class="costbar"><i style="width:${c.baseline?Math.min(100,c.alternative/c.baseline*100):0}%"></i></div>${rows([[`Severance for ${total-count} ${total-count===1?'person':'people'}`,c.remainingSeverance],[`Recruiting + onboarding for ${openings-count}`,c.alternativeHiring],['Training + transfer admin',c.training+c.transferAdmin]])}</div><div class="costcard saving"><h3>${c.saving>=0?'Estimated transition costs avoided':'Additional transition costs'}</h3><strong>${cash(Math.abs(c.saving))}</strong><p>${count} ${count===1?'person':'people'} potentially retained.<br>${openings-count} vacancies still need external hires.<br>${total-count} ${total-count===1?'person needs':'people need'} a broader placement review.</p><p>${c.baseline?Math.abs(c.saving/c.baseline*100).toFixed(0):0}% ${c.saving>=0?'lower':'higher'} modeled transition cost.</p></div></div><div class="economicsnote">Same ${openings} available ${openings===1?'role':'roles'} filled in both scenarios. Savings come from avoided severance and external hiring, less training and transfer costs. This is a one time estimate, not annual salary savings. Proposed moves assume successful training.</div>`;$('summary').classList.remove('hidden');$('summary').innerHTML=`<div class="summetric"><strong>${count} of ${total}</strong><span>possible internal moves</span></div><div class="summetric"><strong>${cash(c.saving)}</strong><span>${c.saving>=0?'estimated transition costs avoided':'additional transition costs'}</span></div><div class="summetric"><strong>${total-count}</strong><span>without a current match</span></div>`;}
function run(scroll=true){result=findMatches(inputs());filter='all';renderPeople();renderEconomics();renderDepartments();renderCompetition();$('analyze').innerHTML='Recalculate matches <span>↗</span>';$('export').disabled=false;$('runState').textContent=`${result.moves.length} proposed moves · ${cash(result.training)} training allocated.`;$('step2').classList.add('current');$('step3').classList.add('current');if(scroll)$('workspace').scrollIntoView({behavior:'smooth',block:'start'});}
$('analyze').onclick=()=>run();['weeks','budget','department','closing','competition'].forEach(id=>$(id).onchange=()=>{if(id==='competition'){$('department').value=$('competition').checked?'Customer Operations':'all';$('department').disabled=$('competition').checked;$('closing').checked=false;}$('competitionNote').classList.toggle('hidden',!$('competition').checked);$('closing').disabled=$('department').value==='all';if($('closing').disabled)$('closing').checked=false;if(result)run(false);else{filter='all';renderPeople();renderDepartments();renderCompetition();}});['hire','severance','onboard','admin'].forEach(id=>$(id).oninput=()=>{assumptions();renderDetail();renderEconomics();});$('people').onclick=e=>{const b=e.target.closest('[data-person]');if(b){selected=b.dataset.person;renderPeople();if(window.matchMedia('(max-width: 750px)').matches)$('detail').scrollIntoView({behavior:'smooth',block:'start'});}};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderPeople();});$('vacancylist').innerHTML=JOBS.map(j=>`<div class="vacancy"><b>${j.title}</b><small>${j.department} · ${j.id.toUpperCase()} · ${cash(j.salary)}/year</small><p>${j.skills.join(' · ')}</p><small>${j.salaryNote}</small></div>`).join('');
$('export').onclick=()=>{if(!result)return;const a=assumptions(),c=costComparison(result,a),rows=[['Workshift: fictional company transition comparison'],['Currency','USD'],['Affected department',inputs().department],['Full department closure',inputs().closing],['Competition example',inputs().competition],['Available vacancies',result.vacancies.length],['Training budget',inputs().budget],['Max training weeks',inputs().weeks],[],['Employee','Current role','Source department','Proposed role','Destination department','Missing skills','Training weeks','Training cost','Estimated transition cost avoided']];result.people.forEach(p=>{const m=moveFor(p.id);rows.push([p.name,p.role,p.department,m?.job.title||'No suitable current match',m?.job.department||'',m?.missing.join('; ')||'',m?.weeks||0,m?.training||0,m?p.salary/52*a.severance+a.hire+a.onboard-m.training-a.admin:0]);});rows.push([],['Broader role possibilities (not placements or savings)'],['Employee','Role family','Destination department','Availability','Planning timing','Skills present','Skills missing','Indicative training weeks','Indicative training cost']);result.people.forEach(p=>careerPossibilities(p,inputs()).forEach(c=>rows.push([p.name,c.job.title,c.job.department,c.job.availability,c.job.timing,c.shared.join('; '),c.missing.join('; '),c.weeks,c.training])));rows.push([],['Baseline transition cost',c.baseline],['Alternative transition cost',c.alternative],['Estimated cost avoided',c.saving],[],['Recruiting cost per hire',a.hire],['Severance weeks',a.severance],['External onboarding per hire',a.onboard],['Internal transfer admin',a.admin],['Recruiting source','https://www.shrm.org/topics-tools/news/talent-acquisition/real-costs-recruitment'],['IT salary source','https://www.bls.gov/ooh/computer-and-information-technology/computer-support-specialists.htm'],['Training salary source','https://www.bls.gov/ooh/business-and-financial/training-and-development-specialists.htm'],['Limitations','Fictional employees and vacancies. Illustrative quotes. No live AI. One time costs only; excludes ongoing pay, salary changes, training payroll, tax and legal fees. Requires human validation.']);const csv=rows.map(r=>r.map(v=>'"'+String(typeof v==='number'?Math.round(v*100)/100:v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='workshift-transition-comparison.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};renderPeople();renderDepartments();

function renderDepartments(){const v=inputs(),cohort=scope().people;$('matchDepartment').textContent=v.department==='all'?'Match all departments ↗':'Match all in '+v.department+' ↗';const available=scope().vacancies;$('vacancyHeading').textContent=`View the ${available.length} available ${available.length===1?'role':'roles'}`;$('vacancylist').innerHTML=available.map(j=>`<div class="vacancy"><b>${j.title}</b><small>${j.department} · ${j.id.toUpperCase()} · ${cash(j.salary)}/year</small><p>${j.skills.join(' · ')}</p><small>${j.salaryNote}</small></div>`).join('');const heading=v.department==='all'?'Where your people could go':`${v.department}: where could the team go?`;let body;if(!result){body=`<p class="breakdownintro">${cohort.length} affected ${cohort.length===1?'employee':'employees'} · ${scope().vacancies.length} available vacancies${v.closing?' outside the closing department':''}. Run matching to see destination departments and people without a fit.</p>`;}else{const b=departmentBreakdown(result);body=`<div class="destinationgrid">${b.rows.map(row=>`<div class="destination"><span class="destinationcount">${row.moves.length}<small> / ${row.openings} openings</small></span><h4>${row.department}</h4>${row.moves.length?row.moves.map(m=>`<button class="personchip" data-open-person="${m.person.id}">${m.person.name}<small>${m.person.department} → ${row.department}</small></button>`).join(''):'<p>No proposed moves into this department.</p>'}</div>`).join('')}<div class="destination nomatch"><span class="destinationcount">${b.unmatched.length}<small> ${b.unmatched.length===1?'person':'people'}</small></span><h4>No current match</h4>${b.unmatched.length?b.unmatched.map(p=>`<button class="personchip" data-open-person="${p.id}">${p.name}<small>${p.department} · Review other options</small></button>`).join(''):'<p>Everyone in this scenario has a proposed move.</p>'}</div></div><p class="breakdownintro">${b.total} ${b.total===1?'person':'people'} accounted for. ${v.closing?'Vacancies in '+v.department+' are excluded because the department is closing.':'Only the selected team is included in this scenario.'} Costs below use the same scope.</p>`;}$('departmentBreakdown').innerHTML=`<div class="breakdownhead"><h3>${heading}</h3><span>${v.closing?'Department closure scenario':'Department breakdown'}</span></div>${body}`;$('runState').textContent=result?`${result.moves.length} proposed moves · ${cash(result.training)} training allocated.`:`Ready to match ${cohort.length} people against ${scope().vacancies.length} openings.`;}
$('departmentBreakdown').onclick=e=>{const b=e.target.closest('[data-open-person]');if(b){selected=b.dataset.openPerson;filter='all';renderPeople();$('detail').scrollIntoView({behavior:'smooth',block:'start'});}};

function futureMarkup(person){const options=careerPossibilities(person,inputs()),v=inputs();return `<div class="futurepossibilities ${detailView==='broader'?'':'hidden'}"><div class="sublabel">CAREER FIT BEYOND TODAY'S OPENINGS</div><p class="futureintro">Skills suggest possible directions, even without a funded vacancy. Planned demand and training estimates below are fictional demo assumptions.</p>${options.length?options.map(c=>`<article class="futurecard"><div class="futurestatus ${c.job.availability}">${c.job.availability==='anticipated'?'Anticipated next month':c.job.availability==='current'?'Role family with current openings':'Exploratory role family'}</div><h4>${c.job.title}</h4><p class="futuredepartment">${c.job.department} · ${c.shared.length} / ${c.job.skills.length} skills present</p><div class="sublabel">SKILLS THAT TRANSFER</div><div class="skills">${c.shared.map(s=>`<span class="skill yes">${s}</span>`).join('')}</div><div class="sublabel">SKILLS TO BUILD</div><div class="skills">${c.missing.length?c.missing.map(s=>`<span class="skill gap">${s}</span>`).join(''):'<span class="skill yes">All listed skills present</span>'}</div><div class="futuretraining"><b>${c.weeks} weeks · ${cash(c.training)}</b><span>Indicative training, subject to assessment${c.weeks>v.weeks?' · exceeds selected timeline':''}${c.training>v.budget?' · exceeds total training budget':''}</span></div><div class="futurebusiness"><b>Potential benefit</b><p>${c.job.benefit||defaultBusinessCase(c.job).benefit}</p><b>When it may not make sense</b><p>${c.job.caution||defaultBusinessCase(c.job).caution}</p></div><p class="futuretiming">${c.job.timing}</p><p class="futurenext">${c.job.availability==='anticipated'?'Next: confirm headcount approval and opening date with the hiring manager.':c.job.availability==='current'?'Next: review the current opening allocation, training limits and role requirements.':'Next: ask the department lead whether this role family appears in the hiring plan.'}</p></article>`).join(''):'<p class="explain">No supported role family in this demo catalog. Expand the skills inventory and role library before drawing a conclusion.</p>'}<p class="futuredisclaimer">Role fit is not a placement or a hiring prediction. Broader possibilities do not consume vacancies, use training budget or change the savings calculation. Closing departments are excluded. Confirm role requirements, employee interest and proficiency first.</p></div>`;}
$('detail').addEventListener('click',e=>{const button=e.target.closest('[data-detail-view]');if(button){detailView=button.dataset.detailView;renderDetail();}});

function defaultBusinessCase(job){const examples={
 'family-it':{benefit:'Use existing company knowledge to resolve technical requests and verify AI assisted fixes.',caution:'Requires validated technical proficiency and enough support demand to justify a role.'},
 'family-ops':{benefit:'Improve recurring reporting by reviewing data quality and checking automated analysis.',caution:'Not justified if reporting demand is already covered or the department is closing.'},
 'family-learning':{benefit:'Help employees learn approved tools through supervised practice.',caution:'Needs a funded learning program and evidence that training improves task performance.'},
 'future-logistics':{benefit:'Reuse dispatch and inventory experience to coordinate planning and verify routing suggestions.',caution:'Requires actual planning demand and approval of the anticipated headcount.'},
 'future-records':{benefit:'Reduce records backlogs and check AI assisted extraction against source documents.',caution:'Useful only with a measurable backlog and a manager responsible for quality.'},
 'family-knowledge':{benefit:'Turn recurring support knowledge into searchable, verified internal guidance.',caution:'Value may be low if documentation is already current or nobody owns maintenance.'},
 'family-enablement':{benefit:'Support onboarding and create practical materials for teams adopting new tools.',caution:'Requires a real onboarding workload; this is not a substitute for specialist training credentials.'}
 };return examples[job.id]||{benefit:'Explore whether these skills solve a documented departmental need.',caution:'Validate demand, proficiency and funding before creating a role.'};}
function renderCompetition(){if(!result){$('candidateComparison').innerHTML='';return;}const v=inputs();$('candidateComparison').innerHTML=`<details class="candidatecomparison" ${v.competition?'open':''}><summary>How were the openings allocated?<span>Skills, training and vacancy limits</span></summary><p class="allocationrule">First maximize people placed within the budget and timeline, then prefer more listed skills, shorter total training and lower training cost. Each person can receive one place. Equal fits need manager review; names only break exact ties in this demo.</p>${result.vacancies.map(job=>{const candidates=vacancyCandidates(result,job),assigned=result.moves.find(m=>m.job.id===job.id);return `<div class="vacancycompetition"><h4>${job.title} <small>${job.id.toUpperCase()} · 1 place</small></h4><p class="allocationdecision">${assigned?'Proposed: '+assigned.person.name+' · '+assigned.shared.length+'/'+job.skills.length+' listed skills · '+assigned.weeks+' weeks training.':'No allocation within the current skill, time and budget constraints.'}</p>${candidates.map(c=>{const placed=result.moves.find(m=>m.person.id===c.person.id),status=placed?.job.id===job.id?'Proposed for this place':placed?'Proposed for '+placed.job.id.toUpperCase():!c.eligible?'Outside current skill rule':c.weeks>v.weeks?'Needs more training time':c.training>v.budget?'Exceeds training budget':'Eligible, no place allocated';return `<button class="candidateitem" data-candidate-person="${c.person.id}"><span><b>${c.person.name}</b><small>${c.shared.length}/${job.skills.length} skills · ${c.eligible?c.weeks+' weeks · '+cash(c.training)+' training':'Training path not established'}</small></span><span class="candidatebadge ${placed?.job.id===job.id?'chosen':''}">${status}</span></button>`;}).join('')}</div>`;}).join('')}</details>`;}
$('matchDepartment').onclick=()=>{run(false);$('departmentBreakdown').scrollIntoView({behavior:'smooth',block:'start'});};
$('candidateComparison').onclick=e=>{const b=e.target.closest('[data-candidate-person]');if(b){selected=b.dataset.candidatePerson;filter='all';detailView='current';renderPeople();$('detail').scrollIntoView({behavior:'smooth',block:'start'});}};
